const sensores = [
    { porta: 1, nome: 'O5D150 - Distancia' },
    { porta: 2, nome: 'KI5309 - Capacitivo' },
    { porta: 3, nome: 'IF6123 - Indutivo' }
];

const idCiclo = Date.now().toString();

return [sensores.map((sensor, index) => {

    return {
        porta: sensor.porta,
        sensor: sensor.nome,
        topic: String(sensor.porta),
        parts: {
            id: idCiclo,
            index: index,
            count: sensores.length,
            type: 'array'
        },
        headers: {
            'Content-Type': 'application/json'
        },
        payload: {
            code: 10,
            cid: Date.now() + index,
            adr: '/iolinkmaster/port[' + sensor.porta + ']/iolinkdevice/pdin/getdata'
        }
    };

})];

const resposta = msg.payload || {};

const valor = resposta.data && resposta.data.value !== undefined
    ? resposta.data.value
    : null;

let distanciaCm = null;
let detectionLevel = null;
let sensorOutput = null;
let pdv1 = null;
let ssc1 = null;
let ssc2 = null;

let status = "Sem informação";

if (resposta.code === 530 && msg.porta === 1) {
    status = "Sem objeto detectado";
}
else if (resposta.code === 200 && valor !== null) {

    const hexadecimal = parseInt(valor, 16);

    if (!Number.isNaN(hexadecimal)) {

        if (msg.porta === 1) {
            distanciaCm = (hexadecimal >> 4) & 0x0FFF;
            status = "Objeto detectado";
        }
        else if (msg.porta === 2) {
            detectionLevel = (hexadecimal >> 8) & 0xFF;
            sensorOutput = hexadecimal & 0x01;
            status = sensorOutput === 1 ? "Saída ativa" : "Saída inativa";
        }
        else if (msg.porta === 3) {
            ssc1 = hexadecimal & 0x01;
            ssc2 = (hexadecimal >> 1) & 0x01;
            pdv1 = (hexadecimal >> 2) & 0x3FFF;

            if (pdv1 & 0x2000) {
                pdv1 -= 0x4000;
            }

            status = "Leitura recebida";
        }

    } else {
        status = "Leitura inválida";
    }

} else {
    status = "Erro na leitura";
}

msg.payload = {
    horario: new Date().toLocaleString('pt-BR'),
    porta: msg.porta,
    sensor: msg.sensor,
    status: status,
    distancia_cm: distanciaCm,
    detection_level: detectionLevel,
    sensor_output: sensorOutput,
    pdv1: pdv1,
    ssc1: ssc1,
    ssc2: ssc2,
    valor_hexadecimal: valor,
    codigo_resposta: resposta.code !== undefined ? resposta.code : null,
    resposta_completa: resposta
};

return msg;

const sensores = msg.payload;

if (!Array.isArray(sensores) || sensores.length !== 3) {
    msg.payload = {
        classificacao: "Inconclusivo",
        motivo: "Não foram recebidas as três leituras."
    };
    return msg;
}

const p1 = sensores.find(s => s.porta === 1);
const p2 = sensores.find(s => s.porta === 2);
const p3 = sensores.find(s => s.porta === 3);

if (!p1 || !p2 || !p3 ||
    (p1.codigo_resposta !== 200 && p1.codigo_resposta !== 530) ||
    p2.codigo_resposta !== 200 ||
    p3.codigo_resposta !== 200) {

    msg.payload = {
        classificacao: "Inconclusivo",
        motivo: "Falha na leitura dos sensores."
    };
    return msg;
}

const semPeca =
    p1.distancia_cm === null ||
    (
        p2.sensor_output === 0 &&
        p3.pdv1 === 8184 &&
        p3.ssc1 === 0 &&
        p3.ssc2 === 0
    );

const metal =
    p3.pdv1 >= 0 &&
    p3.pdv1 <= 4095 &&
    p3.ssc1 === 1 &&
    p3.ssc2 === 1;

const naoMetal =
    p2.sensor_output === 1 &&
    p3.pdv1 === 8184 &&
    p3.ssc1 === 0 &&
    p3.ssc2 === 0;

let classificacao = "Inconclusivo";

if (semPeca) {
    classificacao = "Nenhuma peça detectada";
} else if (metal) {
    classificacao = "Peça metálica";
} else if (naoMetal) {
    classificacao = "Peça não metálica";
}

msg.payload = {
    horario: p1.horario,
    classificacao: classificacao,
    distancia_cm: p1.distancia_cm,
    capacitivo: {
        detection_level: p2.detection_level,
        sensor_output: p2.sensor_output
    },
    indutivo: {
        pdv1: p3.pdv1,
        ssc1: p3.ssc1,
        ssc2: p3.ssc2
    }
};

return msg;

const leitura = msg.payload;

// Quantas leituras seguidas SEM peça para considerar que a peça terminou de passar.
// Com leitura a cada 0,1 s: 10 leituras = 1 segundo sem detecção.
const LEITURAS_PARA_ENCERRAR = 10;

// Valor que o sensor indutivo devolve quando NÃO há metal por perto
const INDUTIVO_SEM_METAL = 8184;

// Verificar se os dados dos sensores chegaram corretamente
if (
    !leitura ||
    !leitura.capacitivo ||
    !leitura.indutivo
) {
    return null;
}

// Verificar presença da peça pelo sensor capacitivo
const pecaPresente =
    leitura.capacitivo.sensor_output === 1;

// Verificar se o sensor indutivo detectou metal
// (mais sensível: qualquer saída ligada OU qualquer valor diferente de "sem metal")
const metalDetectado =
    leitura.indutivo.ssc1 === 1 ||
    leitura.indutivo.ssc2 === 1 ||
    (leitura.indutivo.pdv1 !== null && leitura.indutivo.pdv1 !== INDUTIVO_SEM_METAL);

// Recuperar estado anterior
let emPassagem = context.get("emPassagem") || false;
let metalVisto = context.get("metalVisto") || false;
let leiturasSemPeca = context.get("leiturasSemPeca") || 0;
let totalPecas = context.get("totalPecas") || 0;

// Enquanto o capacitivo detectar a peça
if (pecaPresente) {

    emPassagem = true;
    leiturasSemPeca = 0;

    // Guardar se o indutivo detectou metal em algum momento
    if (metalDetectado) {
        metalVisto = true;
    }

    context.set("emPassagem", emPassagem);
    context.set("metalVisto", metalVisto);
    context.set("leiturasSemPeca", leiturasSemPeca);

    // Ainda não apresentar classificação
    return null;
}

// Se não houver peça, contar leituras consecutivas sem detecção
if (emPassagem) {

    // Continuar olhando o indutivo logo depois que a peça sai do capacitivo
    // (caso o indutivo esteja posicionado depois do capacitivo na esteira)
    if (metalDetectado) {
        metalVisto = true;
        context.set("metalVisto", metalVisto);
    }

    leiturasSemPeca++;

    context.set("leiturasSemPeca", leiturasSemPeca);

    // Esperar várias leituras sem peça para encerrar a passagem
    // (evita que uma "piscada" do sensor divida uma peça em duas)
    if (leiturasSemPeca < LEITURAS_PARA_ENCERRAR) {
        return null;
    }

    // Classificação final
    const classificacao = metalVisto
        ? "Peça metálica"
        : "Peça não metálica";

    totalPecas++;

    // Liberar para a próxima peça
    context.set("emPassagem", false);
    context.set("metalVisto", false);
    context.set("leiturasSemPeca", 0);
    context.set("totalPecas", totalPecas);

    msg.payload = {
        evento: "Passagem finalizada",
        numero_sequencial: totalPecas,
        horario: leitura.horario,
        classificacao: classificacao,
        distancia_cm: leitura.distancia_cm,
        capacitivo: leitura.capacitivo,
        indutivo: leitura.indutivo
    };

    return msg;
}

return null;

// ================= CONFIGURAÇÃO DA API =================
// Troque pelo IP do PC onde o back-end está rodando (comando ipconfig)
// Ex.: 'http://192.168.0.15:8080'. Na nuvem: o endereço HTTPS da API.
const API_URL = 'http://localhost:8080';
const ESTEIRA_ID = 1;
const USUARIO = 'esteira@metaltech.com';
const SENHA = 'esteira123';
// ========================================================

// Recebe a peça finalizada do nó "Controlar passagem de peças"
// e monta o POST /api/leituras/pecas no formato da API.
const dados = msg.payload || {};
let sensorIndutivo;
let sensorCapacitivo;

if (dados.classificacao === 'Peça metálica') {
    sensorIndutivo = true;     // indutivo detectou metal
    sensorCapacitivo = true;   // capacitivo detecta qualquer material
} else if (dados.classificacao === 'Peça não metálica') {
    sensorIndutivo = false;
    sensorCapacitivo = true;
} else {
    return null; // nada a enviar
}

msg.method = 'POST';
msg.url = API_URL + '/api/leituras/pecas';
msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Basic ' + Buffer.from(USUARIO + ':' + SENHA).toString('base64')
};
msg.payload = {
    esteiraId: ESTEIRA_ID,
    sensorIndutivo: sensorIndutivo,
    sensorCapacitivo: sensorCapacitivo
};
node.status({ fill: 'green', shape: 'dot', text: dados.classificacao + ' #' + dados.numero_sequencial });
return msg;

// ================= CONFIGURAÇÃO DA API =================
// Troque pelo IP do PC onde o back-end está rodando (comando ipconfig)
// Ex.: 'http://192.168.0.15:8080'. Na nuvem: o endereço HTTPS da API.
const API_URL = 'http://localhost:8080';
const ESTEIRA_ID = 1;
const USUARIO = 'esteira@metaltech.com';
const SENHA = 'esteira123';
// ========================================================

// Envia o nível do reservatório (sensor de distância O5D150) para
// POST /api/leituras/niveis, no máximo a cada INTERVALO_MS.
const INTERVALO_MS = 5000;
// O valor do sensor vem em "distancia_cm". Se, ao conferir com uma régua,
// o valor estiver em milímetros, troque para 0.1.
const FATOR_PARA_CM = 1;

const dados = msg.payload || {};
if (dados.distancia_cm === null || dados.distancia_cm === undefined) {
    return null; // sem objeto detectado ou falha de leitura
}

const agora = Date.now();
const ultimoEnvio = context.get('ultimoEnvio') || 0;
if (agora - ultimoEnvio < INTERVALO_MS) {
    return null;
}
context.set('ultimoEnvio', agora);

const distanciaCm = Math.round(dados.distancia_cm * FATOR_PARA_CM * 10) / 10;

msg.method = 'POST';
msg.url = API_URL + '/api/leituras/niveis';
msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Basic ' + Buffer.from(USUARIO + ':' + SENHA).toString('base64')
};
msg.payload = {
    esteiraId: ESTEIRA_ID,
    distanciaCm: distanciaCm
};
node.status({ fill: 'blue', shape: 'dot', text: distanciaCm + ' cm' });
return msg;
